Residuals vs. fitted values (code)

spotify_aug &lt;- augment(spotify_fit)

gf_point(.resid ~ .fitted, data = spotify_aug) |&gt;
  gf_hline(yintercept = 0, linetype = "dashed") |&gt;
  gf_labs(
    x = "Fitted value", y = "Residual",
    title = "Residuals vs. fitted values"
  )
